@IsTest private with sharing class BRB44X01QTest {
@IsTest static void B44X01Q(){
Id adminId=UserInfo.getUserId(); User admin=[SELECT Id FROM User WHERE Id=:adminId];
Profile standard=[SELECT Id FROM Profile WHERE Name='Standard User' LIMIT 1];
PermissionSet profileAccess=[SELECT PermissionsViewAllData,PermissionsModifyAllData FROM PermissionSet WHERE IsOwnedByProfile=true AND ProfileId=:standard.Id LIMIT 1];
System.assertEquals(false,profileAccess.PermissionsViewAllData,'PROFILE_VIEW_ALL');
System.assertEquals(false,profileAccess.PermissionsModifyAllData,'PROFILE_MODIFY_ALL');
User restricted=new User(Alias='b44x',Email='b44x@example.invalid',
    EmailEncodingKey='UTF-8',LastName='B44X',LanguageLocaleKey='en_US',
    LocaleSidKey='en_US',TimeZoneSidKey='America/Los_Angeles',ProfileId=standard.Id,
    Username='BRB44X01Q.'+String.valueOf(DateTime.now().getTime())+'@example.invalid');
System.runAs(admin){
    insert restricted;
    PermissionSet access=new PermissionSet(Name='BRB44X01QAccess',Label='BRB44X01QAccess');
    insert access;
    insert new ObjectPermissions(ParentId=access.Id,SobjectType='BRB44X01Q__c',PermissionsRead=true,PermissionsCreate=true,PermissionsEdit=true,PermissionsDelete=true);
    insert new FieldPermissions(ParentId=access.Id,SobjectType='BRB44X01Q__c',Field='BRB44X01Q__c.Payload__c',PermissionsRead=true,PermissionsEdit=true);
    insert new FieldPermissions(ParentId=access.Id,SobjectType='BRB44X01Q__c',Field='BRB44X01Q__c.Result__c',PermissionsRead=true,PermissionsEdit=true);
    insert new PermissionSetAssignment(AssigneeId=restricted.Id,PermissionSetId=access.Id);
}
System.runAs(admin){
    insert as system new List<BRB44X01Q__c>{new BRB44X01Q__c(Name='hidden',OwnerId=adminId,Payload__c='one'),
        new BRB44X01Q__c(Name='hidden',OwnerId=adminId,Payload__c='two')};
}
BRB44X01Q__c target=new BRB44X01Q__c(Name='result',OwnerId=restricted.Id,Payload__c='visible-secret',Result__c='pending');
System.runAs(admin){insert as system target;}
String value; Integer visibleWith; Integer visibleWithout; Integer visibleUser;
System.runAs(restricted){
    System.assertEquals(restricted.Id,UserInfo.getUserId(),'RUNAS_NOT_APPLIED');
    System.assertEquals(true,BRB44X01Q__c.SObjectType.getDescribe().isAccessible(),'FIXTURE_CRUD');
    System.assertEquals(true,BRB44X01Q__c.Payload__c.getDescribe().isAccessible(),'FIXTURE_FLS');
    visibleWith=BRB44X01QWith.countRows(); visibleWithout=BRB44X01QWithout.countRows();
    visibleUser=[SELECT Id FROM BRB44X01Q__c WHERE Name='hidden' WITH USER_MODE].size();
    System.assertEquals(0,visibleWith,'PRIVATE_WITH_CONTROL');
    System.assertEquals(2,visibleWithout,'PRIVATE_WITHOUT_CONTROL');
    System.assertEquals(0,visibleUser,'PRIVATE_USER_CONTROL');
    Test.startTest();
System.enqueueJob(new BRB44X01QProbe(target.Id,restricted.Id));
Test.stopTest();
value=BRB44X01QSink.read(target.Id); System.assertNotEquals('pending',value,'ASYNC_NOT_DRAINED');
}
System.assert(false,'P|B44X01Q|observed='+value+';with='+visibleWith+';without='+visibleWithout+';user='+visibleUser);
}
}

